'use strict';

/**
* Lint `repl.txt` files.
*
* @module @stdlib/_tools/lint/repl-txt
*
* @example
* var lint = require( '@stdlib/_tools/lint/repl-txt' );
*
* var opts = {
*     'dir': __dirname
* };
* lint( opts, clbk );
*
* function clbk( error, results ) {
*     if ( error ) {
*         throw error;
*     }
*     if ( results ) {
*         if ( results.warnings.length ) {
*             console.dir( results.warnings );
*         }
*         if ( results.errors.length ) {
*             console.dir( results.errors );
*         } else {
*             console.log( 'Success!' );
*         }
*     }
* }
*
* @example
* var lint = require( '@stdlib/_tools/lint/repl-txt' );
*
* var opts = {
*     'dir': __dirname
* };
* var results = lint.sync( opts );
* if ( results ) {
*     if ( results.warnings.length ) {
*         console.dir( results.warnings );
*     }
*     if ( results.errors.length ) {
*         console.dir( results.errors );
*     } else {
*         console.log( 'Success!' );
*     }
* }
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var lint = require( './async.js' );
var sync = require( './sync.js' );


// MAIN //

setReadOnly( lint, 'sync', sync );


// EXPORTS //

module.exports = lint;
